class Order private constructor(
    val id: OrderId,
    val customer: CustomerId,
) {
    companion object {
        fun fromCart(cart: Cart): Order {
            require(cart.items.isNotEmpty()) { "empty cart" }
            return Order(OrderId.new(), cart.customerId)
        }
        internal fun rehydrate(id: OrderId, customer: CustomerId) = Order(id, customer)
    }
}
